// HELPERS
// ────────────────────────────────────────────────────────────────
export function gateStats() {
  const total = PRODUCTION_READINESS_GATE.length;
  const byStatus = {
    PASS: PRODUCTION_READINESS_GATE.filter(c => c.status === 'PASS').length,
    PENDING: PRODUCTION_READINESS_GATE.filter(c => c.status === 'PENDING').length,
    FAIL: PRODUCTION_READINESS_GATE.filter(c => c.status === 'FAIL').length,
    'N/A': PRODUCTION_READINESS_GATE.filter(c => c.status === 'N/A').length,
  };
  const bySeverity = {
    CRITICAL: PRODUCTION_READINESS_GATE.filter(c => c.severity === 'CRITICAL').length,
    HIGH: PRODUCTION_READINESS_GATE.filter(c => c.severity === 'HIGH').length,
    MEDIUM: PRODUCTION_READINESS_GATE.filter(c => c.severity === 'MEDIUM').length,
    LOW: PRODUCTION_READINESS_GATE.filter(c => c.severity === 'LOW').length,
  };
  const criticalPending = PRODUCTION_READINESS_GATE.filter(c => c.severity === 'CRITICAL' && c.status !== 'PASS');
  const highPending = PRODUCTION_READINESS_GATE.filter(c => c.severity === 'HIGH' && c.status !== 'PASS');
  return {
    total,
    byStatus,
    bySeverity,
    criticalPending,
    highPending,
    // Gate is GREEN when no CRITICAL is pending
    gateDecision: criticalPending.length === 0 ? 'GREEN' : 'RED',
    gateDecisionReason: criticalPending.length === 0
      ? 'All CRITICAL checkpoints PASS — gate is GREEN.'
      : `${criticalPending.length} CRITICAL checkpoint(s) still PENDING/FAIL — gate RED.`,
  };
}

export function getChecksByCategory(category: GateCheck['category']): GateCheck[] {
  return PRODUCTION_READINESS_GATE.filter(c => c.category === category);
}

export function getCriticalPending(): GateCheck[] {
  return PRODUCTION_READINESS_GATE.filter(c => c.severity === 'CRITICAL' && c.status !== 'PASS');
}
